{
  "findings": [
    {
      "check_id": "CKV_AWS_389",
      "title": "Ensure AWS Auto Scaling group launch configuration doesn't have public IP address assignment enabled",
      "resource": "aws_launch_configuration.lc",
      "severity": "MEDIUM",
      "explanation": "The 'associate_public_ip_address' is set to true, which exposes the instance to the public internet. This increases the attack surface and can lead to unauthorized access."
    },
    {
      "check_id": "CKV_AWS_79",
      "title": "Ensure Instance Metadata Service Version 1 is not enabled",
      "resource": "aws_launch_configuration.lc",
      "severity": "MEDIUM",
      "explanation": "The launch configuration does not explicitly set 'metadata_options', which defaults to allowing IMDSv1. IMDSv1 is less secure and susceptible to SSRF attacks."
    },
    {
      "check_id": "CKV_AWS_8",
      "title": "Ensure all data stored in the Launch configuration or instance Elastic Blocks Store is securely encrypted",
      "resource": "aws_launch_configuration.lc",
      "severity": "MEDIUM",
      "explanation": "The launch configuration does not specify encryption for the root block device or additional EBS volumes, which could lead to unencrypted sensitive data at rest."
    }
  ],
  "patched_code": "resource \"aws_launch_configuration\" \"lc\" {\n  name          = \"test_ecs\"\n  image_id      = data.aws_ami.amazon_linux.id\n  instance_type = \"t2.micro\"\n  lifecycle {\n    create_before_destroy = true\n  }\n  iam_instance_profile        = aws_iam_instance_profile.ecs_service_role.name\n  key_name                    = var.key_name\n  security_groups             = [aws_security_group.ec2-sg.id]\n  associate_public_ip_address = false\n  metadata_options {\n    http_tokens               = \"required\"\n    http_put_response_hop_limit = 1\n  }\n  root_block_device {\n    encrypted = true\n  }\n  user_data                   = <<EOF\nsudo apt-get update\nsudo echo \"ECS_CLUSTER=${var.cluster_name}\" >> /etc/ecs/ecs.config\nEOF\n}",
  "fix_summary": "Disabled public IP assignment by setting 'associate_public_ip_address' to false. Added 'metadata_options' to enforce IMDSv2 and secure metadata access. Enabled encryption for the root block device to ensure data at rest is encrypted."
}
